    environs = {}
    log.debug("starting to collect environs using prefix: '%s'", prefix)
    for arg in args:
        environ = f"{prefix}{name}_{arg}".upper()
        if os.environ.get(environ):
            environs[arg] = os.environ[environ]
    return environs


